solution:
use xiom.io;

use xiom.string;
fn transfer(from: Str, to: Str, amount_str: Str, balance: Float64) -> Result[Float64, Str] {
  let amount = string.str_to_float(amount_str)?;
  if amount <= 0.0 {
    return Err("Transfer amount must be positive");
  }
  if amount > balance {
    return Err("Insufficient funds");
  }
  if from == to {
    return Err("Cannot transfer to the same account");
  }
  return Ok(balance - amount);
}

fn main() -> Int {
  match transfer("Alice", "Bob", "100", 500.0) {
    Ok(new_balance) => { return (new_balance * 100.0) as Int; }
    Err(_) => { return -1; }
  }
}
